function store():any{if(!sqlite)return JSON.parse(fs.readFileSync(root+'/treasury-db.json','utf8'));const s=new SqliteRecords<any>(root+'/treasury.sqlite',false,true);try{return s.read();}finally{s.close();}}
async function api(route:string,who?:string,body?:any){const r=await fetch(base+'/api'+route,{method:body?'POST':'GET',headers:{'content-type':'application/json',...(who?{authorization:'Bearer '+tokens[who]}:{})},...(body?{body:JSON.stringify(body)}:{})});return{status:r.status,data:await r.json()};}
async function start(){const entry=process.env.TREASURY_TEST_SERVER;child=spawn(process.execPath,['--import',pathToFileURL(path.resolve('tests/fail-commit.mjs')).href,'--import',pathToFileURL(path.resolve('tests/outbound-guard.mjs')).href,...(entry?[entry]:['--import',pathToFileURL(path.resolve('tests/native-types.mjs')).href,path.resolve('server.ts')]),'--host','127.0.0.1','--port',String(port)],{cwd:entry?path.dirname(entry):process.cwd(),env:{PATH:process.env.PATH,SystemRoot:process.env.SystemRoot,NODE_ENV:'production',TREASURY_DATA_DIR:root,TREASURY_TEST_DIR:root,TREASURY_STORAGE_MODE:sqlite?'sqlite':'json',DISABLE_EXTERNAL_INTEGRATIONS:'true',TREASURY_ACCOUNT_INQUIRIES_ENABLED:'true'},windowsHide:true,stdio:'ignore'});for(let i=0;i<160;i++){if(child.exitCode!==null)throw Error('Synthetic inquiry server exited');try{if((await fetch(base+'/api/health')).ok)return;}catch{}await new Promise(r=>setTimeout(r,75));}throw Error('Synthetic inquiry server startup timeout');}
async function stop(){if(child?.exitCode===null&&child.signalCode===null){const ended=new Promise(r=>child.once('exit',r));child.kill();await ended;}}
before(async()=>{try{await fetch(base+'/api/health');throw Error('Occupied fixture port');}catch(e:any){if(e.message==='Occupied fixture port')throw e;}fs.mkdirSync(root,{recursive:true});if(sqlite){const s=new SqliteRecords(root+'/treasury.sqlite',true);try{s.commit(data,undefined,s.signature());}finally{s.close();}}else fs.writeFileSync(root+'/treasury-db.json',JSON.stringify(data),{flag:'wx'});await start();for(const u of data.users){const r=await api('/auth/login',undefined,{personnelCode:u.id,password});assert.equal(r.status,200);tokens[u.id]=r.data.token;}});after(stop);
const op=()=>crypto.randomUUID(),raw=(q:any)=>store().accountInquiries.find((x:any)=>x.id===q.id),row=(q:any,index=0)=>raw(q).rows[index];
async function create(who='employee',extra:any={}){const before=new Set(store().accountInquiries.map((q:any)=>q.id)),r=await api('/account-inquiries/create',who,{operationId:op(),origin:'SELF',companyId:'C',title:'TEST statement',information:['BALANCE'],...extra,rows:(extra.rows||[{question:'TEST balance'}]).map((r:any)=>({financialIntent:r.financialIntent||(r.subject?.kind==='EMPLOYEE'?'ADVANCE':'PAYMENT'),...r}))});assert.equal(r.status,200,JSON.stringify(r.data));return store().accountInquiries.find((q:any)=>!before.has(q.id));}
async function action(q:any,who:string,kind:string,extra:any={},index=0){const r=row(q,index);return api('/account-inquiries/action',who,{operationId:op(),inquiryId:q.id,rowId:r.id,expectedVersion:r.version,action:kind,...extra});}
async function approve(q:any){assert.equal((await action(q,'lead','APPROVE')).status,200);}
async function respond(q:any,who='accounting',extra:any={},index=0){const r=row(q,index);return api('/account-inquiries/respond',who,{operationId:op(),inquiryId:q.id,rowId:r.id,expectedVersion:r.version,kind:'COMPLETE',identityVerified:true,text:'PRIVATE-TEST-ONLY',balance:5000,direction:'COMPANY_OWES',asOf:'1405/08/04',fileIds:[],...extra});}
async function view(q:any,who='employee'){const r=await api('/account-inquiries',who);assert.equal(r.status,200);return r.data.inquiries.find((x:any)=>x.id===q.id);}
