test('manual personnel advance requires explicit confirmation by the actual authorized financial creator',async()=>{const q=await create('lead',{origin:'OTHERS',rows:[{financialIntent:'ADVANCE',subject:{kind:'EMPLOYEE',name:'TEST manual staff'}}]});assert.equal((await respond(q)).status,200);const financial={title:'TEST personnel confirmation',items:[{amount:100,costCenter:'TEST',description:'TEST staff advance'}]},blocked=await convert(q,'lead',{kind:'ADVANCE_BATCH',financial});assert.equal(blocked.status,400);assert.equal(blocked.data.code,'PERSONNEL_CONFIRMATION_REQUIRED');assert.equal(row(q).financialResult,undefined);const accepted=await convert(q,'lead',{kind:'ADVANCE_BATCH',financial,confirmPersonnel:true});assert.equal(accepted.status,200,JSON.stringify(accepted.data));assert.equal(row(q).financialResult.personnelConfirmed,true);assert.equal(row(q).financialResult.actorId,'lead');});
test('identity and intent correction re-enters review; retry is stable and the old response cannot create money',async()=>{const q=await others(),first=await respond(q);assert.equal(first.status,200);const oldReplyId=row(q).replies.at(-1).id;assert.equal((await respond(q,'accounting',{kind:'NEEDS_INFORMATION',text:'TEST clarify identity'})).status,200);const current=row(q),body={operationId:op(),inquiryId:q.id,rowId:current.id,expectedVersion:current.version,action:'RESUBMIT',reason:'TEST correct person and purpose',subject:{kind:'EMPLOYEE',userId:'employee'},financialIntent:'ADVANCE'};assert.equal((await api('/account-inquiries/action','lead',body)).status,200);const newVersion=row(q).version;assert.equal(row(q).status,'PENDING_ACCOUNTING');assert.equal(row(q).subject.userId,'employee');assert.equal(row(q).financialIntent,'ADVANCE');assert.equal(row(q).replies[0].subjectSnapshot.kind,'SUPPLIER');assert.equal(row(q).replies[0].financialIntent,'PAYMENT');assert.equal((await api('/account-inquiries/action','lead',body)).status,200);assert.equal(row(q).version,newVersion);assert.equal((await api('/account-inquiries/action','lead',{...body,financialIntent:'PAYMENT'})).status,409);const stale=await convert(q,'lead',{kind:'ADVANCE_BATCH',targets:[{inquiryId:q.id,rowId:row(q).id,expectedVersion:row(q).version,replyId:oldReplyId}],financial:{title:'TEST stale',items:[{amount:100,costCenter:'TEST',description:'TEST'}]}});assert.equal(stale.status,409);assert.equal(row(q).financialResult,undefined);assert.equal((await respond(q)).status,200);assert.equal(row(q).replies.at(-1).subjectSnapshot.userId,'employee');assert.equal(row(q).replies.at(-1).financialIntent,'ADVANCE');const wrong=await convert(q,'lead');assert.equal(wrong.status,400);assert.equal(wrong.data.code,'FINANCIAL_INTENT_MISMATCH');assert.equal((await convert(q,'lead',{kind:'ADVANCE_BATCH',financial:{title:'TEST corrected',items:[{amount:100,costCenter:'TEST',description:'TEST'}]}})).status,200);});
async function others(rows:any[]=[supplier()],information=['BALANCE']){return create('lead',{origin:'OTHERS',rows,information});}
async function upload(q:any,who='accounting',name='TEST.txt',content='PRIVATE-TEST-ONLY',operationId=op()){return api('/account-inquiries/upload',who,{operationId,inquiryId:q.id,rowId:row(q).id,name,data:'data:text/plain;base64,'+Buffer.from(content).toString('base64')});}
async function convert(q:any,who='employee',extra:any={}){const r=row(q);return api('/account-inquiries/financial-request',who,{operationId:op(),kind:'PAYMENT_SINGLE',targets:[{inquiryId:q.id,rowId:r.id,expectedVersion:r.version,replyId:r.replies.at(-1)?.id}],financial:{amount:12000,description:'TEST conversion',payeeName:'FORGED',costCenter:'TEST',accountOrCard:'0'.repeat(16)},...extra});}
async function released(intent='PAYMENT'){const q=await create('employee',{rows:[{question:'TEST balance',financialIntent:intent}]});await approve(q);assert.equal((await respond(q)).status,200);assert.equal((await action(q,'lead','RELEASE')).status,200);return q;}

async function linked(count=1){const targets=[];for(let i=0;i<count;i++){const result=await api('/payment-requests','employee',{amount:12000,payeeName:'TEST LINK '+i,description:'TEST consultation',costCenter:'TEST',accountOrCard:'0'.repeat(16)});assert.equal(result.status,200);const p=result.data.item;targets.push({itemType:'PAYMENT',requestId:p.id,expectedVersion:p.version,expectedStatus:p.status});}return create('lead',{origin:'FINANCIAL_REVIEW',rows:targets.map(financialTarget=>({financialTarget,question:'TEST ORIGINAL QUESTION'}))});}
const editBody=(q:any,extra:any={})=>({operationId:op(),inquiryId:q.id,expectedVersion:raw(q).version,information:['STATEMENT','EXPLANATION'],asOf:'1405/08/04',fromDate:'',toDate:'',rows:raw(q).rows.map((r:any)=>({id:r.id,question:'TEST EDITED QUESTION'})),...extra});
test('linked initial edit snapshots old information, bumps every row and notifies the current accounting queue atomically',async()=>{const q=await linked(2),before=structuredClone(raw(q)),finance=JSON.stringify(store().paymentRequests),body=editBody(q);assert.equal((await api('/account-inquiries/edit','lead',body)).status,200);const after=raw(q);assert.deepEqual(after.information,['STATEMENT','EXPLANATION']);assert.equal(after.version,before.version+1);for(let i=0;i<2;i++){assert.equal(after.rows[i].version,before.rows[i].version+1);assert.deepEqual(after.rows[i].financialSource,before.rows[i].financialSource);assert.deepEqual(after.rows[i].subject,before.rows[i].subject);assert.equal(after.rows[i].question,'TEST EDITED QUESTION');assert.ok(after.rows[i].audit.some((a:any)=>a.action==='EDIT_REQUEST'&&a.reason.includes('TEST ORIGINAL QUESTION')));}assert.ok(after.audit.some((a:any)=>a.action==='EDIT_REQUEST'&&a.reason.includes('مانده حساب')));assert.equal(JSON.stringify(store().paymentRequests),finance);for(const who of['accounting','accounting2'])assert.equal((await api('/state',who)).data.notifications.filter((n:any)=>n.accountInquiryRef?.inquiryId===q.id&&n.accountInquiryRef.purpose==='RESPOND').length,2);assert.equal((await api('/state','otherlead')).data.notifications.some((n:any)=>n.accountInquiryRef?.inquiryId===q.id),false);});
test('initial edit denies another reader, standalone inquiries, source or identity changes, incomplete rows and stale versions',async()=>{const q=await linked(2),before=JSON.stringify(raw(q));for(const who of['accounting','otherlead','foreign','admin'])assert.equal((await api('/account-inquiries/edit',who,editBody(q))).status,403);const separate=await others();assert.equal((await api('/account-inquiries/edit','lead',editBody(separate))).status,403);for(const extra of[{rows:[editBody(q).rows[0]]},{companyId:'OTHER'},{financialSource:{requestId:'forged'}},{information:[]},{fromDate:'1405/08/05',toDate:'1405/08/04'},{rows:editBody(q).rows.map((r:any)=>({...r,subject:{name:'FORGED'}}))}])assert.equal((await api('/account-inquiries/edit','lead',editBody(q,extra))).status,400);assert.equal((await api('/account-inquiries/edit','lead',editBody(q,{expectedVersion:0}))).status,409);assert.equal(JSON.stringify(raw(q)),before);});
test('every accounting response kind locks all initial fields, including an unanswered sibling',async()=>{for(const kind of['COMPLETE','NEEDS_INFORMATION','UNAVAILABLE']){const q=await linked(2);assert.equal((await respond(q,'accounting',{kind,text:'TEST response'})).status,200);const before=JSON.stringify(raw(q));const r=await api('/account-inquiries/edit','lead',editBody(q));assert.equal(r.status,409);assert.equal(r.data.code,'INQUIRY_EDIT_LOCKED');assert.equal(JSON.stringify(raw(q)),before);}});
test('edit and response racing from the same snapshot have one winner and never attach an old answer to a new requirement',async()=>{const q=await linked(),r=row(q),body=editBody(q),answer={operationId:op(),inquiryId:q.id,rowId:r.id,expectedVersion:r.version,kind:'COMPLETE',identityVerified:true,text:'TEST race response',balance:5000,direction:'COMPANY_OWES',asOf:'1405/08/04',fileIds:[]};const results=await Promise.all([api('/account-inquiries/edit','lead',body),api('/account-inquiries/respond','accounting',answer)]);assert.deepEqual(results.map(r=>r.status).sort(),[200,409]);if(results[0].status===200){assert.equal(row(q).replies.length,0);assert.deepEqual(raw(q).information,['STATEMENT','EXPLANATION']);}else{assert.equal(row(q).replies.length,1);assert.deepEqual(raw(q).information,['BALANCE']);}});
test('old response version is denied after edit and a committed edit replays after the later answer without another effect',async()=>{const q=await linked(),oldVersion=row(q).version,body=editBody(q);assert.equal((await api('/account-inquiries/edit','lead',body)).status,200);assert.equal((await respond(q,'accounting',{expectedVersion:oldVersion})).status,409);assert.equal((await respond(q)).status,200);const before=JSON.stringify(raw(q)),notes=store().notifications.length;const replay=await api('/account-inquiries/edit','lead',body);assert.equal(replay.status,200);assert.equal(replay.data.replayed,true);assert.equal(JSON.stringify(raw(q)),before);assert.equal(store().notifications.length,notes);assert.equal((await api('/account-inquiries/edit','lead',{...body,information:['BALANCE']})).status,409);});
test('failed edit commit leaves request, history and notifications unchanged and the same command retries once',async()=>{const q=await linked(),body=editBody(q),before=JSON.stringify(raw(q)),notes=JSON.stringify(store().notifications);fs.writeFileSync(root+'/test-fail-next-commit','TEST');assert.equal((await api('/account-inquiries/edit','lead',body)).status,500);assert.equal(JSON.stringify(raw(q)),before);assert.equal(JSON.stringify(store().notifications),notes);assert.equal((await api('/account-inquiries/edit','lead',body)).status,200);assert.equal((await api('/account-inquiries/edit','lead',body)).status,200);assert.equal(raw(q).audit.filter((a:any)=>a.action==='EDIT_REQUEST').length,1);});
test('linked conversation remains readable after financial approval and follow-up preserves the posted answer and money',async()=>{const q=await linked(),source=row(q).financialSource,parent=store().paymentRequests.find((p:any)=>p.id===source.requestId);assert.equal((await api('/review/row-action','lead',{itemType:'PAYMENT',requestId:parent.id,expectedVersion:parent.version,expectedStatus:parent.status,reviewStage:'APPROVER',action:'APPROVE'})).status,200);assert.equal(store().paymentRequests.find((p:any)=>p.id===source.requestId).status,'Pending_Accounting');assert.equal((await view(q,'lead')).rows[0].financialSource.expectedStatus,'Pending_Approver');assert.equal((await respond(q)).status,200);const finance=JSON.stringify(store().paymentRequests.find((p:any)=>p.id===source.requestId)),reply=structuredClone(row(q).replies[0]);assert.equal((await action(q,'lead','FOLLOW_UP',{reason:'TEST send the statement too'})).status,200);assert.deepEqual(row(q).replies[0],reply);assert.equal((await respond(q)).status,200);assert.equal(row(q).replies.length,2);assert.equal(JSON.stringify(store().paymentRequests.find((p:any)=>p.id===source.requestId)),finance);});

test('a response arriving after the displayed GET cannot be silently marked read by that older view',async()=>{const q=await others();assert.equal((await respond(q)).status,200);const seen=row(q).version;assert.equal((await respond(q,'accounting',{text:'PRIVATE-LATER-RESPONSE'})).status,200);const latest=row(q).replies.at(-1).id,notice=store().notifications.find((n:any)=>n.accountInquiryRef?.replyId===latest&&n.recipientUserId==='lead');assert.ok(notice);const read=await api('/account-inquiries/read','lead',{inquiryId:q.id,rowId:row(q).id,expectedVersion:seen});assert.equal(read.status,409);assert.equal(store().notifications.find((n:any)=>n.id===notice.id).readByUserIds.includes('lead'),false);assert.equal((await api('/account-inquiries/read','lead',{inquiryId:q.id,rowId:row(q).id})).status,409);assert.equal((await api('/account-inquiries/read','lead',{inquiryId:q.id,rowId:row(q).id,expectedVersion:row(q).version})).status,200);assert.equal(store().notifications.find((n:any)=>n.id===notice.id).readByUserIds.includes('lead'),true);});

test('inquiry counters follow only the assigned stage and do not expose a private accounting response',async()=>{const lead0=(await api('/state','lead')).data.accountInquirySummary,acc0=(await api('/state','accounting')).data.accountInquirySummary,other0=(await api('/state','otherlead')).data.accountInquirySummary,mine0=(await api('/state','employee')).data.accountInquirySummary;const q=await create();assert.equal((await api('/state','lead')).data.accountInquirySummary.approval,lead0.approval+1);assert.equal((await api('/state','otherlead')).data.accountInquirySummary.approval,other0.approval);assert.equal((await api('/state','employee')).data.accountInquirySummary.mine,mine0.mine+1);await approve(q);assert.equal((await api('/state','lead')).data.accountInquirySummary.approval,lead0.approval);assert.equal((await api('/state','accounting')).data.accountInquirySummary.accounting,acc0.accounting+1);assert.equal((await respond(q)).status,200);const own=(await api('/state','employee')).data;assert.equal(own.accountInquirySummary.mineNew,mine0.mineNew);assert.equal(own.notifications.some((n:any)=>n.accountInquiryRef?.inquiryId===q.id),false);assert.equal(JSON.stringify(own.accountInquirySummary).includes('PRIVATE-TEST'),false);assert.ok((await api('/state','lead')).data.accountInquirySummary.release>lead0.release);});
test('reply alerts survive later actions, target the right tab and are read only by the authorized row viewer',async()=>{const q=await released(),r=row(q);let own=(await api('/state','employee')).data;const note=own.notifications.find((n:any)=>n.accountInquiryRef?.inquiryId===q.id&&n.accountInquiryRef.purpose==='VIEW');assert.ok(note?.accountInquiryRef.replyId);assert.equal(note.accountInquiryRef.targetTab,'MINE');assert.equal((await convert(q)).status,200);own=(await api('/state','employee')).data;assert.ok(own.notifications.some((n:any)=>n.id===note.id));const leadNote=(await api('/state','lead')).data.notifications.find((n:any)=>n.accountInquiryRef?.inquiryId===q.id&&n.accountInquiryRef.purpose==='VIEW');assert.equal(leadNote.accountInquiryRef.targetTab,'HISTORY');const before=JSON.stringify(row(q));assert.equal((await api('/account-inquiries/read','otherlead',{inquiryId:q.id,rowId:r.id,expectedVersion:row(q).version})).status,403);assert.equal((await api('/account-inquiries/read','foreign',{inquiryId:q.id,rowId:r.id,expectedVersion:row(q).version})).status,403);const mineBefore=own.accountInquirySummary.mineNew;for(let i=0;i<2;i++)assert.equal((await api('/account-inquiries/read','employee',{inquiryId:q.id,rowId:r.id,expectedVersion:row(q).version,userId:'lead'})).status,200);assert.equal(JSON.stringify(row(q)),before);const after=(await api('/state','employee')).data;assert.equal(after.accountInquirySummary.mineNew,mineBefore-1);assert.ok(after.notifications.find((n:any)=>n.id===note.id).readByUserIds.includes('employee'));assert.equal(store().notifications.find((n:any)=>n.id===leadNote.id).readByUserIds.includes('lead'),false);});
test('new private reply does not inherit publication or create a new requester alert before release',async()=>{const q=await released();assert.equal((await api('/account-inquiries/read','employee',{inquiryId:q.id,rowId:row(q).id,expectedVersion:row(q).version})).status,200);const count=(await api('/state','employee')).data.accountInquirySummary.mineNew;assert.equal((await respond(q,'accounting',{text:'PRIVATE-NEW-UNRELEASED',balance:6000})).status,200);const own=(await api('/state','employee')).data;assert.equal(own.accountInquirySummary.mineNew,count);assert.equal(JSON.stringify(own.notifications).includes('PRIVATE-NEW-UNRELEASED'),false);assert.equal((await view(q)).rows[0].replies.length,1);assert.equal((await action(q,'lead','RELEASE')).status,200);assert.equal((await api('/state','employee')).data.accountInquirySummary.mineNew,count+1);});
test('revision and resubmission update counters once per row and notify all eligible accountants only',async()=>{const q=await create(),original=(await api('/state','employee')).data.accountInquirySummary;assert.equal((await action(q,'lead','RETURN',{reason:'TEST supply detail'})).status,200);assert.equal((await api('/state','employee')).data.accountInquirySummary.mineNew,original.mineNew+1);const r=row(q),body={operationId:op(),inquiryId:q.id,rowId:r.id,expectedVersion:r.version,action:'RESUBMIT',reason:'TEST supplemented'};assert.equal((await api('/account-inquiries/action','employee',body)).status,200);assert.equal((await api('/account-inquiries/action','employee',body)).status,200);assert.equal((await api('/state','employee')).data.accountInquirySummary.mineNew,original.mineNew);await approve(q);for(const who of ['accounting','accounting2'])assert.equal((await api('/state',who)).data.notifications.filter((n:any)=>n.accountInquiryRef?.inquiryId===q.id&&n.accountInquiryRef.purpose==='RESPOND').length,1);for(const who of ['employee2','otherlead','treasury','foreign','selfaccounting'])assert.equal((await api('/state',who)).data.notifications.some((n:any)=>n.accountInquiryRef?.inquiryId===q.id),false);});
test('read receipts work in safe read-only mode and cannot mutate finance or inquiry versions',async()=>{const q=await released(),r=row(q),before=JSON.stringify(row(q));assert.equal((await api('/account-inquiries/admin','admin',{operationId:op(),action:'SET_READ_ONLY',readOnly:true,reason:'TEST read receipt in safe mode'})).status,200);try{assert.equal((await api('/account-inquiries/read','employee',{inquiryId:q.id,rowId:r.id,expectedVersion:row(q).version})).status,200);assert.equal(JSON.stringify(row(q)),before);}finally{assert.equal((await api('/account-inquiries/admin','admin',{operationId:op(),action:'SET_READ_ONLY',readOnly:false,reason:'TEST restore normal mode'})).status,200);}});

test('additive inquiry schema preserves old profiles; raw collections never appear in state/auth/sync responses',async()=>{const db=store();assert.equal(db.accountInquirySchemaVersion,2);for(const u of data.users){const current=db.users.find((x:any)=>x.id===u.id);for(const key of ['role','additionalRoles','passwordHash','passwordSalt','supervisorId','requestApprovers'])assert.deepEqual(current[key],u[key]);}const q=await create();for(const who of ['admin','employee','accounting','treasury']){const state=await api('/state',who);assert.equal(state.status,200);for(const key of ['accountInquiries','accountInquiryFiles','accountInquiryOperations'])assert.ok(!state.data[key]?.length);assert.equal(JSON.stringify(state.data).includes(q.trackingCode)&&JSON.stringify(state.data).includes('PRIVATE-TEST-ONLY'),false);}assert.equal((await api('/account-inquiries','treasury')).status,403);});
test('personal inquiry first goes to exactly its own supervisor; another supervisor cannot read or approve',async()=>{const q=await create();assert.equal(row(q).status,'PENDING_APPROVER');assert.equal(q.approverId,'lead');assert.equal((await action(q,'otherlead','APPROVE')).status,403);assert.equal(await view(q,'otherlead'),undefined);assert.equal((await action(q,'employee','APPROVE')).status,403);await approve(q);assert.equal(row(q).status,'PENDING_ACCOUNTING');});
test('missing supervisor fails closed; explicit direct routing and direct answer work',async()=>{const r=await api('/account-inquiries/create','noroute',{operationId:op(),origin:'SELF',companyId:'C',title:'TEST no route',information:['BALANCE'],rows:[{}]});assert.equal(r.status,400);assert.equal(r.data.code,'INQUIRY_ROUTE_REQUIRED');const q=await others();assert.equal(q.approverId,null);assert.equal(row(q).status,'PENDING_ACCOUNTING');assert.equal((await respond(q)).status,200);assert.equal((await view(q,'lead')).rows[0].replies.length,1);});
test('initial approval does not release answer; a separate release exposes exactly that version',async()=>{const q=await create();await approve(q);assert.equal((await respond(q)).status,200);let v=await view(q);assert.equal(v.rows[0].replies.length,0);assert.equal(JSON.stringify(v).includes('PRIVATE-TEST-ONLY'),false);assert.equal((await action(q,'employee','RELEASE')).status,403);assert.equal((await action(q,'lead','RELEASE')).status,200);v=await view(q);assert.equal(v.rows[0].replies.length,1);assert.equal(v.rows[0].replies[0].balance,5000);assert.match(v.rows[0].replies[0].asOf,/^2026-/);});
test('internal handling keeps response private; new answer does not inherit old release',async()=>{const q=await create();await approve(q);assert.equal((await respond(q)).status,200);assert.equal((await action(q,'lead','HANDLE_INTERNALLY',{reason:'TEST private followup'})).status,200);assert.equal((await view(q)).rows[0].replies.length,0);const x=await released(),old=row(x).replies[0].id;assert.equal((await respond(x,'accounting',{balance:6000,text:'PRIVATE-NEW-VERSION'})).status,200);const v=await view(x);assert.deepEqual(v.rows[0].replies.map((x:any)=>x.id),[old]);assert.equal(JSON.stringify(v).includes('PRIVATE-NEW-VERSION'),false);assert.equal((await convert(x)).status,409);});
test('accounting plus requester roles cannot reply to own inquiry; a different accountant can',async()=>{const q=await create('accounting');assert.equal((await respond(q,'accounting')).status,403);assert.equal((await respond(q,'accounting2')).status,200);assert.equal((await view(q,'accounting')).rows[0].replies.length,1);});
test('foreign company, ordinary requests for others and unrelated subordinate are denied',async()=>{const body={operationId:op(),origin:'OTHERS',companyId:'C',title:'TEST',information:['BALANCE'],rows:[supplier()]};assert.equal((await api('/account-inquiries/create','employee',body)).status,403);assert.equal((await api('/account-inquiries/create','foreign',{...body,operationId:op(),origin:'SELF'})).status,403);assert.equal((await api('/account-inquiries/create','lead',{...body,operationId:op(),rows:[{subject:{kind:'EMPLOYEE',userId:'employee2'}}]})).status,403);});
test('same display names and grouped responses stay separate by row and party identity',async()=>{const q=await others([supplier('TEST SAME'),supplier('TEST SAME')]);assert.notEqual(row(q,0).id,row(q,1).id);assert.equal((await respond(q,'accounting',{balance:7000},0)).status,200);assert.equal(row(q,1).status,'PENDING_ACCOUNTING');assert.equal((await respond(q,'accounting2',{balance:9000},1)).status,200);const v=await view(q,'lead');assert.deepEqual(v.rows.map((r:any)=>r.replies[0].balance),[7000,9000]);});
test('clarification for a personal request is also private until released, then returns to accounting',async()=>{const q=await create();await approve(q);assert.equal((await respond(q,'accounting',{kind:'NEEDS_INFORMATION',text:'PRIVATE-CLARIFICATION'})).status,200);assert.equal((await view(q)).rows[0].replies.length,0);assert.equal(row(q).status,'AWAITING_RELEASE');assert.equal((await action(q,'lead','RELEASE')).status,200);assert.equal(row(q).status,'NEEDS_REVISION');assert.equal((await action(q,'employee','RESUBMIT',{reason:'TEST clarified'})).status,200);assert.equal(row(q).status,'PENDING_ACCOUNTING');assert.equal((await respond(q)).status,200);});
test('private attachments require exact released reply; neither treasury nor another company can download',async()=>{const q=await create();await approve(q);const uploaded=await upload(q);assert.equal(uploaded.status,200);const file=uploaded.data.file;assert.equal((await respond(q,'accounting',{fileIds:[file.id]})).status,200);const request=(who:string)=>fetch(base+'/api/account-inquiries/files/'+file.id,{headers:{authorization:'Bearer '+tokens[who]}});assert.equal((await request('employee')).status,403);assert.equal((await request('foreign')).status,403);assert.equal((await request('treasury')).status,403);assert.equal(JSON.stringify(await view(q)).includes(file.name),false);assert.equal((await action(q,'lead','RELEASE')).status,200);const response=await request('employee');assert.equal(response.status,200);assert.equal(await response.text(),'PRIVATE-TEST-ONLY');assert.equal(response.headers.get('x-content-type-options'),'nosniff');assert.match(response.headers.get('content-disposition')||'',/^attachment/);});
test('file type, path and payload validation rejects active content and invalid date/balance',async()=>{const q=await others();assert.equal((await upload(q,'accounting','bad.svg','<svg/>')).status,400);assert.equal((await upload(q,'accounting','../bad.txt','TEST')).status,400);assert.equal((await upload(q,'accounting','bad.pdf','NOT PDF')).status,400);assert.equal((await respond(q,'accounting',{balance:-1})).status,400);assert.equal((await respond(q,'accounting',{balance:0,direction:'COMPANY_OWES'})).status,400);assert.equal((await respond(q,'accounting',{identityVerified:false})).status,400);assert.equal((await respond(q,'accounting',{asOf:'2026-02-31'})).status,400);});
test('file written before failed DB commit remains invisible; same operation retries safely',async()=>{const q=await others(),operationId=op(),fileId='afi-'+crypto.createHash('sha256').update('accounting:'+operationId).digest('hex').slice(0,32);fs.writeFileSync(root+'/test-fail-next-commit','TEST');assert.equal((await upload(q,'accounting','retry.txt','TEST retry',operationId)).status,500);assert.ok(fs.existsSync(root+'/account-inquiry-files/'+fileId));assert.ok(!store().accountInquiryFiles.some((f:any)=>f.id===fileId));assert.equal((await fetch(base+'/api/account-inquiries/files/'+fileId,{headers:{authorization:'Bearer '+tokens.accounting}})).status,404);const r=await upload(q,'accounting','retry.txt','TEST retry',operationId);assert.equal(r.status,200);assert.equal((await upload(q,'accounting','retry.txt','TEST retry',operationId)).status,200);assert.equal(store().accountInquiryFiles.filter((f:any)=>f.id===fileId).length,1);});
test('released response conversion uses ordinary actor routing and cannot turn others into a self advance',async()=>{const q=await released();const r=await convert(q);assert.equal(r.status,200,JSON.stringify(r.data));const payment=store().paymentRequests.find((x:any)=>x.id===row(q).financialResult.requestId);assert.equal(payment.requesterId,'employee');assert.equal(payment.payeeName,'TEST employee');assert.equal(payment.supervisorId,'lead');assert.equal(payment.status,'Pending_Approver');assert.equal((await convert(q)).status,409);const other=await others([{subject:{kind:'EMPLOYEE',userId:'employee'}}]);assert.equal((await respond(other)).status,200);assert.equal((await convert(other,'lead',{kind:'ADVANCE_SINGLE',financial:{amount:12000,reason:'TEST'}})).status,403);});
test('two users racing one inquiry row create one financial target and repeat preserves the same result',async()=>{const q=await released(),r=row(q),body={operationId:op(),kind:'PAYMENT_SINGLE',targets:[{inquiryId:q.id,rowId:r.id,expectedVersion:r.version,replyId:r.replies.at(-1).id}],financial:{amount:12000,description:'TEST race',costCenter:'TEST',accountOrCard:'0'.repeat(16)}},before=store().paymentRequests.length;const a=await Promise.all([api('/account-inquiries/financial-request','employee',body),api('/account-inquiries/financial-request','lead',{...body,operationId:op()})]);assert.deepEqual(a.map(x=>x.status).sort(),[200,409]);assert.equal(store().paymentRequests.length,before+1);const winner=a[0].status===200?'employee':'lead',payload=winner==='employee'?body:null;if(payload){assert.equal((await api('/account-inquiries/financial-request',winner,payload)).status,200);assert.equal(store().paymentRequests.length,before+1);}});
test('group conversion binds each source row to its exact child in one normal financial request',async()=>{const q=await others([supplier('TEST vendor1'),supplier('TEST vendor2')]);assert.equal((await respond(q,'accounting',{},0)).status,200);assert.equal((await respond(q,'accounting',{},1)).status,200);const targets=raw(q).rows.map((r:any)=>({inquiryId:q.id,rowId:r.id,expectedVersion:r.version,replyId:r.replies.at(-1).id}));const result=await convert(q,'lead',{kind:'PAYMENT_BATCH',targets,financial:{title:'TEST financial batch',items:targets.map(()=>({amount:12000,description:'TEST',costCenter:'TEST',accountOrCard:'0'.repeat(16)}))}});assert.equal(result.status,200,JSON.stringify(result.data));const batch=store().batchPayments.find((x:any)=>x.id===row(q).financialResult.requestId);assert.equal(batch.items.length,2);assert.equal(batch.status,'Pending_Accounting');for(let i=0;i<2;i++)assert.equal(row(q,i).financialResult.rowId,batch.items[i].id);});
test('conversion commit failure leaves both relation and financial store unchanged; retry commits once',async()=>{const q=await released(),r=row(q),body={operationId:op(),kind:'PAYMENT_SINGLE',targets:[{inquiryId:q.id,rowId:r.id,expectedVersion:r.version,replyId:r.replies.at(-1).id}],financial:{amount:12000,description:'TEST atomic',costCenter:'TEST',accountOrCard:'0'.repeat(16)}},before=JSON.stringify(store().paymentRequests);fs.writeFileSync(root+'/test-fail-next-commit','TEST');assert.equal((await api('/account-inquiries/financial-request','employee',body)).status,500);assert.equal(JSON.stringify(store().paymentRequests),before);assert.equal(row(q).financialResult,undefined);assert.equal((await api('/account-inquiries/financial-request','employee',body)).status,200);assert.equal((await api('/account-inquiries/financial-request','employee',body)).status,200);});
test('open consultation neither advances financial approval nor blocks treasury; late response cannot rewrite a paid record',async()=>{const r=await api('/payment-requests','employee',{amount:12000,payeeName:'TEST vendor',description:'TEST late',costCenter:'TEST',accountOrCard:'0'.repeat(16)});assert.equal(r.status,200);const p=r.data.item,q=await create('lead',{origin:'FINANCIAL_REVIEW',rows:[{financialTarget:{itemType:'PAYMENT',requestId:p.id,expectedVersion:p.version,expectedStatus:p.status}}]});assert.equal(store().paymentRequests.find((x:any)=>x.id===p.id).status,'Pending_Approver');for(const who of ['lead','accounting']){const current=store().paymentRequests.find((x:any)=>x.id===p.id);assert.equal((await api('/review/row-action',who,{itemType:'PAYMENT',requestId:p.id,expectedVersion:current.version,expectedStatus:current.status,reviewStage:who==='lead'?'APPROVER':'ACCOUNTING',action:'APPROVE'})).status,200);}assert.equal((await api('/treasury/execute-payment','treasury',{items:[{type:'PAYMENT',id:p.id}],paymentAmount:12000,sourceBankAccountId:'A',bankRefNumber:'TEST',idempotencyKey:'TEST-'+op()})).status,200);const paid=JSON.stringify(store().paymentRequests.find((x:any)=>x.id===p.id));assert.equal((await respond(q)).status,200);assert.equal(JSON.stringify(store().paymentRequests.find((x:any)=>x.id===p.id)),paid);assert.equal(await view(q,'employee'),undefined);assert.equal((await convert(q,'lead')).status,400);});
test('open inquiry blocks supervisor offboarding; case-specific admin reassignment retains old audit',async()=>{const q=await create();const r=await api('/users/toggle-status','admin',{targetUserId:'lead',isActive:false});assert.equal(r.status,409);assert.equal(r.data.code,'OPEN_WORK_BLOCKS_ACCESS_CHANGE');const current=raw(q),m=await api('/account-inquiries/admin','admin',{operationId:op(),action:'REASSIGN_APPROVER',inquiryId:q.id,expectedVersion:current.version,newApproverId:'otherlead',reason:'TEST recorded reassignment'});assert.equal(m.status,200);assert.equal(raw(q).approverId,'otherlead');assert.ok(raw(q).audit.some((a:any)=>a.reason==='TEST recorded reassignment'));assert.equal((await action(q,'otherlead','APPROVE')).status,200);});
test('notification audiences are named, stage-bound and contain no balance or confidential explanation',async()=>{const q=await create();const pending=(await api('/state','lead')).data.notifications.filter((n:any)=>n.requestId===q.id);assert.ok(pending.length);assert.equal((await api('/state','otherlead')).data.notifications.some((n:any)=>n.requestId===q.id),false);assert.equal((await api('/state','accounting')).data.notifications.some((n:any)=>n.requestId===q.id),false);await approve(q);assert.equal((await api('/state','lead')).data.notifications.some((n:any)=>n.requestId===q.id),false);assert.ok((await api('/state','accounting')).data.notifications.some((n:any)=>n.requestId===q.id));assert.equal((await respond(q)).status,200);const notes=store().notifications.filter((n:any)=>n.requestId===q.id);assert.ok(notes.every((n:any)=>!n.body.includes('PRIVATE-TEST')&&!n.body.includes('5000')));assert.equal((await api('/state','employee')).data.notifications.some((n:any)=>n.requestId===q.id),false);});
test('inquiry safe mode closes only inquiry writes; ordinary financial submission remains available',async()=>{const set=(readOnly:boolean)=>api('/account-inquiries/admin','admin',{operationId:op(),action:'SET_READ_ONLY',readOnly,reason:'TEST safe mode'});assert.equal((await set(true)).status,200);const r=await api('/account-inquiries/create','employee',{operationId:op(),origin:'SELF',companyId:'C',title:'TEST',information:['BALANCE'],rows:[{}]});assert.equal(r.status,409);assert.equal(r.data.code,'INQUIRIES_READ_ONLY');assert.equal((await api('/advance-requests','employee',{amount:12000,reason:'TEST normal flow remains'})).status,200);assert.equal((await set(false)).status,200);});
