test('completed inquiry cannot reopen or receive a new reply at an unqualified former reviewer; qualified admin replacement restores the path',async()=>{const role='TEMP_INQUIRY_REVIEWER';assert.equal((await api('/roles/save','admin',{role,title:'TEST temporary reviewer',baseTemplateRole:'APPROVER',permissions:rolePermissions('APPROVER'),accessScope:'ASSIGNED_AND_SUBORDINATES',allowedCompanies:['TEST'],approvalLimitRial:1000000,paymentLimitRial:1000000})).status,200);const save=async(personnelCode:string,extra:any)=>{const r=await api('/users/save','admin',{name:'TEST '+personnelCode,personnelCode,password,company:'TEST',department:'TEST',isActive:true,mustChangePassword:false,phone:'',...extra});assert.equal(r.status,200,JSON.stringify(r.data));const u=store().users.find((u:any)=>u.personnelCode===personnelCode);const login=await api('/auth/login',undefined,{personnelCode,password});assert.equal(login.status,200);tokens[personnelCode]=login.data.token;return u;};const supervisor=await save('temp-reviewer',{role,accessScope:'ASSIGNED_AND_SUBORDINATES',financialApprovalLimit:1000000});await save('temp-employee',{role:'REQUESTER',accessScope:'SELF_ONLY',supervisorId:supervisor.id});const q=await create('temp-employee');assert.equal((await action(q,'temp-reviewer','APPROVE')).status,200);const replyOperation=op(),replyVersion=row(q).version;assert.equal((await api('/roles/save','admin',{role,permissions:{canReleaseAccountInquiry:false}})).status,409);assert.equal((await respond(q,'accounting',{operationId:replyOperation})).status,200);assert.equal((await action(q,'temp-reviewer','RELEASE')).status,200);assert.equal((await api('/roles/save','admin',{role,permissions:{canReleaseAccountInquiry:false}})).status,200);const replyCount=row(q).replies.length;const replay=await respond(q,'accounting',{operationId:replyOperation,expectedVersion:replyVersion});assert.equal(replay.status,200);assert.equal(replay.data.replayed,true);assert.equal(row(q).replies.length,replyCount);assert.equal((await action(q,'temp-employee','FOLLOW_UP',{reason:'TEST reopen'})).status,409);assert.equal((await respond(q)).status,409);let current=raw(q);assert.equal((await api('/account-inquiries/admin','admin',{operationId:op(),action:'REASSIGN_APPROVER',inquiryId:q.id,expectedVersion:current.version,newApproverId:'approveonly',reason:'TEST invalid successor'})).status,400);current=raw(q);assert.equal((await api('/account-inquiries/admin','admin',{operationId:op(),action:'REASSIGN_APPROVER',inquiryId:q.id,expectedVersion:current.version,newApproverId:'otherlead',reason:'TEST qualified successor'})).status,200);assert.equal((await action(q,'temp-employee','FOLLOW_UP',{reason:'TEST reopened after successor'})).status,200);assert.equal(row(q).status,'PENDING_ACCOUNTING');});

